fn main() {
    let _args: Vec<String> = std::env::args().collect();

    let mut bar = ProgressBar::new();
    bar.set_progress(45);
    bar.set_total(90);
    bar.set_width(40);
    println!("{}", bar.str());
    println!("{}", bar.call());

    let pct1 = Percentage::new(0.45, 1);
    let pct2 = Percentage::new(0.67, 2);
    println!("{}", pct1.str());
    println!("{}", pct2.str());
    println!("{}", pct1);

    let cnt = Counter::new(45, 90);
    println!("{}", cnt.str());
    println!("{}", cnt);

    let mut builder = ProgressBuilder::new();
    println!("{}", builder.set_progress(45).set_total(90).build());

    let mut tracker = ProgressTracker::new();
    tracker.add_stage("A").add_stage("B").add_stage("C");
    tracker.set_progress(1);
    tracker.set_total(3);
    println!("{}", tracker.get_progress());
    println!("{}", tracker.get_percentage());

    println!("{}", Format::percentage_default(0.33));
    println!("{}", Format::progress(33, 100));
    println!("{}", Format::bar(33, 100, 25));

    let mut multi = MultiProgress::new();
    let mut b1 = ProgressBar::new();
    let mut b2 = ProgressBar::new();
    b1.set_progress(30);
    b1.set_total(100);
    b2.set_progress(60);
    b2.set_total(100);
    multi.add_bar(b1);
    multi.add_bar(b2);
    println!("{}", multi.str());

    let mut display = ProgressDisplay::new(100);
    display.update(50);
    println!("{}", display.display());
    display.increment(25);
    println!("{}", display.display());

    let mut cyclic = CyclicProgress::new(10);
    cyclic.next();
    cyclic.next();
    println!("{}", cyclic.str());

    let mut task = TaskProgress::new("Test", 10);
    task.complete(3);
    println!("{}", task.status());

    for i in 1..=5 {
        println!("{}", Format::percentage(0.12345, i));
    }

    for i in (10..=50).step_by(10) {
        println!("{}", Format::bar(50, 100, i));
    }

    let mut counters = [Counter::default(); 3];
    for (index, counter) in counters.iter_mut().enumerate() {
        counter.set_current((index + 1) * 25);
        counter.set_total(100);
        println!("{}", counter.str());
    }

    let percentages = [
        Percentage::new(0.25, 1),
        Percentage::new(0.5, 2),
        Percentage::new(0.75, 3),
    ];

    for percentage in percentages {
        println!("{}", percentage.str());
    }
}

