pub struct Format;

impl Format {
    pub fn percentage(value: f32, precision: usize) -> String {
        format!("{:.*}%", precision, value * 100.0)
    }

    pub fn percentage_default(value: f32) -> String {
        Self::percentage(value, 1)
    }

    pub fn progress(current: usize, total: usize) -> String {
        format!("{current}/{total}")
    }

    pub fn bar(current: usize, total: usize, width: usize) -> String {
        let ratio = progress_ratio(current, total);
        let body = if width == 0 {
            String::new()
        } else if ratio >= 1.0 {
            "=".repeat(width)
        } else {
            let filled = (ratio * width as f32).floor() as usize;
            let tail = width.saturating_sub(filled + 1);
            format!("{}>{}", "=".repeat(filled.min(width)), " ".repeat(tail))
        };

        format!("[{body}] {}", Self::percentage_default(ratio))
    }
}

pub(crate) fn progress_ratio(current: usize, total: usize) -> f32 {
    if total == 0 {
        0.0
    } else {
        (current as f32 / total as f32).clamp(0.0, 1.0)
    }
}

