use std::fmt;

use crate::indicators::formatting::progress_ratio;
use crate::indicators::Format;

const FRAMES: [&str; 8] = ["⣾", "⣽", "⣻", "⢿", "⡿", "⣟", "⣯", "⣷"];

#[derive(Clone, Debug)]
pub struct CyclicProgress {
    total: usize,
    current: usize,
    frame_index: usize,
}

impl CyclicProgress {
    pub fn new(total: usize) -> Self {
        Self {
            total,
            current: 0,
            frame_index: 0,
        }
    }

    pub fn next(&mut self) -> &mut Self {
        if self.current < self.total {
            self.current += 1;
        }
        self.frame_index = (self.frame_index + 1) % FRAMES.len();
        self
    }

    pub fn str(&self) -> String {
        format!(
            "{} {}",
            FRAMES[self.frame_index],
            Format::percentage_default(progress_ratio(self.current, self.total))
        )
    }
}

impl fmt::Display for CyclicProgress {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.str())
    }
}

