    current: usize,
}

impl ProgressDisplay {
    pub fn new(total: usize) -> Self {
        Self { total, current: 0 }
    }

    pub fn update(&mut self, current: usize) -> &mut Self {
        self.current = current.min(self.total);
        self
    }

    pub fn increment(&mut self, amount: usize) -> &mut Self {
        self.current = self.current.saturating_add(amount).min(self.total);
        self
    }

    pub fn display(&self) -> String {
        format!(
            "Progress: {} ({}/{})",
            Format::percentage_default(progress_ratio(self.current, self.total)),
            self.current,
            self.total
        )
    }
}
